    private static Variant Get(Settings d, string key, Variant fallback = default) => d.TryGetValue(key, out var value) ? value : fallback;
    private static double Finite(Variant v, double fallback) { double value = v.VariantType is Variant.Type.Int or Variant.Type.Float ? v.AsDouble() : fallback; return double.IsFinite(value) ? value : fallback; }
    public Godot.Collections.Array<Settings> presets() { var result = new Godot.Collections.Array<Settings>(); foreach (var item in Json.ParseString(PresetsJson).AsGodotArray()) result.Add(item.AsGodotDictionary()); return result; }
    public Settings patch(string id, string label, string kind, double attack, double decay, double sustain, double release, double cutoff, Settings extra)
    {
        var result = new Settings { ["id"] = id, ["label"] = label, ["kind"] = kind, ["attack"] = attack, ["decay"] = decay, ["sustain"] = sustain, ["release"] = release, ["filter"] = cutoff, ["resonance"] = 0.0, ["detune"] = 0.0, ["modulation"] = 0.0, ["vibrato"] = 0.0, ["vibrato_rate"] = 5.0, ["width"] = 0.0, ["gain"] = .55, ["seed"] = 1, ["effects"] = new GArray() }; result.Merge(extra, true); return result;
    }
    public Settings default_instrument(string id) { if (id == "drum_kit") id = "drums"; var all = presets(); foreach (var entry in all) if (entry["id"].AsString() == id) return entry.Duplicate(true); return all[7].Duplicate(true); }
    public double midi_frequency(double pitch) => 440 * Math.Pow(2, (pitch - 69) / 12);
    public double number(Settings settings, string key, double fallback, double low, double high) => Math.Clamp(Finite(Get(settings, key, fallback), fallback), low, high);
    public double held_envelope(double t, double attack, double decay, double sustain) { if (t < attack) return t / Math.Max(attack, .000001); if (t < attack + decay) return Mathf.Lerp(1, sustain, (t - attack) / Math.Max(decay, .000001)); return sustain; }
    public double envelope(double t, double gate, double attack, double decay, double sustain, double release) { double level = held_envelope(Math.Min(t, gate), attack, decay, sustain); if (t > gate) level *= Math.Max(0, 1 - (t - gate) / Math.Max(.00001, release)); return level; }
    public Settings sample_mapping(Settings patch, int pitch, double velocity)
    {
        string kind = Get(patch, "kind", "").AsString(); if (kind == "sampler") return patch; if (kind != "multisample") return new Settings();
        foreach (var raw in Get(patch, "multisamples", new GArray()).AsGodotArray()) { if (raw.VariantType != Variant.Type.Dictionary) continue; var entry = raw.AsGodotDictionary(); if (pitch >= Get(entry, "low", 0).AsInt64() && pitch <= Get(entry, "high", 127).AsInt64() && velocity >= Get(entry, "velocity_low", 0.0).AsDouble() && velocity <= Get(entry, "velocity_high", 1.0).AsDouble()) return entry; }
        return new Settings();
    }
    public Vector2 sample_at(Vector2[] data, double position) { if (position < 0 || position >= data.Length - 1) return Vector2.Zero; int index = (int)position; double fade = Math.Min(1, position / 64) * Math.Min(1, (data.Length - 1.0 - position) / 64); return data[index].Lerp(data[index + 1], (float)(position - index)) * (float)fade; }
    public double table(GArray table, double phase) { double position = (phase - Math.Floor(phase)) * table.Count; int index = (int)position; return Mathf.Lerp(Finite(table[index], 0), Finite(table[(index + 1) % table.Count], 0), position - index); }
    public double note_bend(GArray points, double beat)
    {
        var previous = Vector2.Zero;
        foreach (var raw in points) { if (raw.VariantType != Variant.Type.Dictionary) continue; var entry = raw.AsGodotDictionary(); var point = new Vector2((float)Get(entry, "time", 0.0).AsDouble(), (float)Get(entry, "semitones", 0.0).AsDouble()); if (point.X > beat) return Mathf.Lerp(previous.Y, point.Y, Math.Clamp((beat - previous.X) / Math.Max(.000001, point.X - previous.X), 0, 1)); previous = point; }
        return previous.Y;
    }
    public double[] lowpass_coeff(double cutoff, double resonance, int rate)
    {
        double omega = Math.Tau * Math.Clamp(cutoff, 20, rate * .44) / rate, cosine = Math.Cos(omega), alpha = Math.Sin(omega) / (2 * (.5 + resonance * 8)), a0 = 1 + alpha;
        return new[] { (1 - cosine) * .5 / a0, (1 - cosine) / a0, (1 - cosine) * .5 / a0, -2 * cosine / a0, (1 - alpha) / a0 };
    }
    private static double Filter(double value, double[] coeff, double[] state) { double output = coeff[0] * value + coeff[1] * state[0] + coeff[2] * state[1] - coeff[3] * state[2] - coeff[4] * state[3]; state[1] = state[0]; state[0] = value; state[3] = state[2]; state[2] = double.IsFinite(output) ? output : 0; return state[2]; }
